<script setup lang="ts">
import { ref } from 'vue'
import type { TxtImportPreview, TxtImportOwnership, TxtCreationMethod } from '../../../desktop/src/contracts/library/import-types'
import type { BookApi } from '../api/writing'
import { messageOf } from '../api/http'
const props = defineProps<{ api: BookApi }>(), emit = defineEmits<{ close: []; imported: [] }>()
const preview = ref<TxtImportPreview | null>(null), error = ref(''), busy = ref(false), ownership = ref<TxtImportOwnership>('owned'), method = ref<TxtCreationMethod>('human'), selected = ref<number[]>([]), title = ref('')
async function read(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; busy.value = true; error.value = ''; preview.value = null
  try { if (file.size > 1024 * 1024 || !/\.(txt|md)$/i.test(file.name)) throw new Error('请选择不超过 1 MiB 的 UTF-8 TXT 或 Markdown 文件。'); const content = new TextDecoder('utf-8', { fatal: true }).decode(await file.arrayBuffer()); preview.value = await props.api.previewImport(file.name, content); title.value = preview.value.suggestedTitle; selected.value = preview.value.chapters.filter(c => c.selectedByDefault).map(c => c.sourceIndex) } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
async function commit() { if (!preview.value) return; busy.value = true; error.value = ''; try { await props.api.commitImport({ token: preview.value.token, ownership: ownership.value, creationMethod: method.value, title: title.value, selectedChapterIndexes: selected.value }); emit('imported') } catch (e) { error.value = messageOf(e) } finally { busy.value = false } }
</script>
<template><div class="modal-backdrop"><section class="paper-card dialog-card" v-dialog="() => { if (!busy) emit('close') }" role="dialog" aria-modal="true" aria-label="导入作品"><header><h2>导入稿件</h2><button :disabled="busy" @click="emit('close')">关闭</button></header><p>先预览，再确认导入。支持 UTF-8 编码的 TXT / Markdown，单文件不超过 1 MiB。</p><label>选择文件<input type="file" accept=".txt,.md,text/plain,text/markdown" :disabled="busy" @change="read"></label><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="busy" role="status">正在处理…</p><div v-if="preview" class="import-preview"><label>导入标题<input v-model="title"></label><label>稿件用途<select v-model="ownership"><option value="owned">导入我的正文</option><option value="material">作为创作资料</option><option value="external">外部参考资料</option></select></label><label v-if="ownership === 'owned'">创作方式<select v-model="method"><option value="human">人工创作</option><option value="ai">AI 创作</option><option value="mixed">人机共同创作</option></select></label><p>{{ preview.chapterCount }} 章 · {{ preview.wordCount }} 字</p><p v-for="warning in preview.warnings" :key="warning" class="warning">{{ warning }}</p><label v-for="chapter in preview.chapters" :key="chapter.sourceIndex" class="check-label"><input v-model="selected" type="checkbox" :value="chapter.sourceIndex"><span>{{ chapter.title }} · {{ chapter.wordCount }} 字<small v-for="issue in chapter.issues" :key="issue">{{ issue }}</small></span></label><button class="primary" :disabled="busy || (ownership === 'owned' && !selected.length)" @click="commit">确认导入所选内容</button></div></section></div></template>
